use std::path::PathBuf;
use std::sync::LazyLock;

use regex::Regex;

use crate::declare_rule;
use crate::lint::context::SourceContext;
use crate::lint::diagnostic::{Diagnostic, Location};
use crate::lint::file_tree::EntryKind;
use crate::lint::rule::SourceRule;

pub struct ConfigureGeneratedFileInSource;

declare_rule! {
    /// A `config.cache`, `config.log` or `config.status` file, as generated by
    /// GNU autoconf `configure` scripts, is shipped in the Source tree or
    /// Source package Patched files.
    ///
    /// Files under `debian/` are ignored. Regular files and hardlinks are
    /// flagged; symlinks and directories are not. Extra is empty; the path is
    /// the Location.
    ConfigureGeneratedFileInSource,
    code = "LN0739",
    tag = "configure-generated-file-in-source",
    default_selected = true,
    experimental = false,
}

// The dot is unescaped, as in lintian, so any single character matches.
static NAME: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"^config.(?:cache|log|status)$").expect("valid regex"));

impl SourceRule for ConfigureGeneratedFileInSource {
    fn run(&self, ctx: &mut SourceContext<'_>) {
        let Some(files) = ctx.files() else {
            return;
        };
        let paths: Vec<PathBuf> = files
            .query()
            .kinds([EntryKind::RegularFile, EntryKind::Hardlink])
            .into_iter()
            .filter(|entry| {
                if entry.path().starts_with("debian") {
                    return false;
                }
                entry
                    .path()
                    .file_name()
                    .and_then(|name| name.to_str())
                    .is_some_and(|name| NAME.is_match(name))
            })
            .map(|entry| entry.path().to_path_buf())
            .collect();
        for path in paths {
            ctx.diagnostic(Diagnostic::warn("").with_location(Location {
                path,
                line: None,
                column: None,
            }));
        }
    }
}

#[cfg(test)]
mod tests {
    use crate::lint::tester::{SourcePackageCase, SourcePackageTester, SourceTreeTester, TestFile};

    use super::*;

    const CONTROL: &str = "Source: example\n\
         Maintainer: Example <ex@example.com>\n\
         Standards-Version: 4.7.2\n\
         \n\
         Package: example\n\
         Architecture: all\n\
         Description: example\n extra\n";

    fn tree(extra: &[(&str, TestFile)]) -> Vec<(String, TestFile)> {
        let mut files = vec![("debian/control".to_string(), TestFile::from(CONTROL))];
        files.extend(
            extra
                .iter()
                .map(|(path, file)| (path.to_string(), file.clone())),
        );
        files
    }

    #[test]
    fn test() {
        let pass = vec![
            tree(&[]),
            tree(&[("debian/config.cache", TestFile::new("x"))]),
            tree(&[("config.cache.bak", TestFile::new("x"))]),
            tree(&[("config.h", TestFile::new("x"))]),
            tree(&[("config.cache", TestFile::symlink("x"))]),
            tree(&[("config.cache", TestFile::directory())]),
        ];
        let fail = vec![
            tree(&[("config.cache", TestFile::new("x"))]),
            tree(&[("config.log", TestFile::new("x"))]),
            tree(&[("config.status", TestFile::new("x"))]),
            tree(&[("tests/config.cache", TestFile::new("x"))]),
            tree(&[("sub/dir/config.status", TestFile::new("x"))]),
            // lintian's unescaped dot matches any character
            tree(&[("configXcache", TestFile::new("x"))]),
        ];
        SourceTreeTester::new(ConfigureGeneratedFileInSource, pass, fail).test_and_snapshot();
    }

    #[test]
    fn test_source_package() {
        let pass = vec![SourcePackageCase::from(tree(&[]))];
        let fail = vec![SourcePackageCase::from(tree(&[(
            "config.cache",
            TestFile::new("x"),
        )]))];
        SourcePackageTester::new(ConfigureGeneratedFileInSource, pass, fail).test_and_snapshot();
    }
}
